// ---------------------------------------------------------------------------
// Deterministic PRNG (mulberry32). Used ONLY to vary filler amounts within a
// controlled range for "plain" vouchers. Every structural choice (which types,
// which dates, which vouchers are defects) is laid out explicitly below so the
// fixture set stays auditable by inspection, not by re-running the RNG.
// ---------------------------------------------------------------------------
const SEED = 0x45434f47; // 'ECOG' spelled in hex-ish — fixed. Changing this changes every filler amount.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function rand() {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(SEED);

/** Deterministic "N.00" / "N.50" rupee amount in [minRupees, maxRupees). */
function amountIn(minRupees, maxRupees) {
  const rupees = minRupees + Math.floor(rand() * (maxRupees - minRupees));
  const paise = rand() < 0.5 ? '00' : '50';
  return `${rupees}.${paise}`;
}

