function addDaysIso(isoDate, days) {
  const d = new Date(`${isoDate}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** Deterministic spread over Apr 1 - May 31 (61 days). 61 and 7 are coprime -> long non-repeating cycle. */
function plainDate(index) {
  return addDaysIso('2026-04-01', (index * 7) % 61);
}

