const vouchers = []; // { voucher_id, voucher_no, voucher_type, voucher_date, created_at, modified_at, lines: [...] }

function tsFor(dateIso, hour = '09:00:00') {
  return `${dateIso}T${hour}+05:30`;
}

/**
 * @param opts.lines array of { ledger_code, debit, credit, party_code, party_name, payment_method, tax_bucket,
 *   narration, reference_no, includeInTB }. includeInTB defaults to true.
 */
function addVoucher({ voucher_id, voucher_no, voucher_type, voucher_date, created_at, modified_at, lines }) {
  vouchers.push({
    voucher_id,
    voucher_no,
    voucher_type,
    voucher_date,
    created_at: created_at ?? tsFor(voucher_date),
    modified_at: modified_at ?? created_at ?? tsFor(voucher_date),
    lines: lines.map((l, i) => ({
      line_no: i + 1,
      ledger_name: LEDGERS[l.ledger_code] ?? (l.ledger_code === ORPHAN_LEDGER_CODE ? ORPHAN_LEDGER_NAME : ''),
      party_code: '',
      party_name: '',
      payment_method: '',
      tax_bucket: '',
      narration: '',
      reference_no: '',
      includeInTB: true,
      ...l,
    })),
  });
}

function twoLine({ voucher_id, voucher_no, voucher_type, voucher_date, drLedger, crLedger, amount, extra = {}, created_at, modified_at }) {
  addVoucher({
    voucher_id,
    voucher_no,
    voucher_type,
    voucher_date,
    created_at,
    modified_at,
    lines: [
      { ledger_code: drLedger, debit: amount, credit: '0.00', ...extra },
      { ledger_code: crLedger, debit: '0.00', credit: amount, ...extra },
    ],
  });
}

